# UAUD (Untrapped Auto-Update & Diagnostics) ver 1.0.0 - TRUE BASELINE
# UAUD diagnoses and orchestrates. UARD repairs. Baseline 1.0.0 may only be retained or upgraded.
$ErrorActionPreference='SilentlyContinue'
$UAUDName='UAUD (Untrapped Auto-Update & Diagnostics)';$UAUDVersion='1.0.0';$UARDName='UARD (Untrapped Auto-Repair Diagnostic)';$UARDVersion='1.0.0'
$Root=Split-Path -Parent $MyInvocation.MyCommand.Path;$Parent=Split-Path -Parent $Root;$ReportPath=Join-Path $Root 'diagnostic-latest.txt';$RepairPath=Join-Path $Root 'self-repair.ps1'
$Middleman='https://untrapped-update-middleman-production.up.railway.app/v1/artifact/'
$log=New-Object 'System.Collections.Generic.List[string]';$initialProblems=@();$repairResult='NOT RUN';$deployment='NOT NEEDED';$UARDNeeded=$false;$middlemanUnknown=@()
$core=@('config.json','packet-filter.ps1','self-repair.ps1','status-untrapped.ps1','ultra-mode.ps1');$ext=@('manifest.json','background.js','content.js','popup.html','popup.js','bootstrap.bundle.min.js')
function Log([string]$s){$x='['+(Get-Date -Format HH:mm:ss)+'] '+$s;Write-Host $x;[void]$log.Add($x)}
function Hash([byte[]]$b){$h=[Security.Cryptography.SHA256]::Create();try{return ([BitConverter]::ToString($h.ComputeHash($b))).Replace('-','').ToLowerInvariant()}finally{$h.Dispose()}}
function Remote([string]$p){try{$r=Invoke-WebRequest -Uri ($Middleman+$p+'?cb='+[DateTime]::UtcNow.Ticks) -UseBasicParsing -TimeoutSec 45 -ErrorAction Stop;if($r.StatusCode -ne 200){throw 'HTTP '+$r.StatusCode};return [Text.Encoding]::UTF8.GetBytes([string]$r.Content)}catch{Log ('[MIDDLEMAN] UNAVAILABLE '+$p+': '+$_.Exception.Message);return $null}}
function Same([string]$rp,[string]$lp){if(!(Test-Path -LiteralPath $lp)){return $false};$r=Remote $rp;if($null -eq $r){return $null};try{return (Hash ([IO.File]::ReadAllBytes($lp))) -eq (Hash $r)}catch{return $false}}
function HTTPS([string]$h){try{return (Test-NetConnection $h -Port 443 -WarningAction SilentlyContinue).TcpTestSucceeded}catch{return $false}}
function StateWord([bool]$v,[string]$yes,[string]$no){if($v){return $yes};return $no}
function IsUntrappedManifest([string]$dir){$m=Join-Path $dir 'manifest.json';if(-not(Test-Path $m)){return $false};try{return ([string](Get-Content $m -Raw|ConvertFrom-Json).name) -eq 'Untrapped'}catch{return $false}}
function BraveCopies{$o=@();if(IsUntrappedManifest $Parent){$o+=$Parent;Log ('[BRAVE] Developer/source extension found: '+$Parent)};$ud=Join-Path $env:LOCALAPPDATA 'BraveSoftware\Brave-Browser\User Data';if(Test-Path $ud){foreach($p in @(Get-ChildItem $ud -Directory -ErrorAction SilentlyContinue|Where-Object{$_.Name -eq 'Default' -or $_.Name -like 'Profile *'})){ $ep=Join-Path $p.FullName 'Extensions';if(Test-Path $ep){foreach($v in @(Get-ChildItem $ep -Directory -Recurse -ErrorAction SilentlyContinue)){foreach($z in @(Get-ChildItem $v.FullName -Directory -ErrorAction SilentlyContinue)){if(IsUntrappedManifest $z){$o+=$z.FullName}}}}}};foreach($proc in @(Get-CimInstance Win32_Process -ErrorAction SilentlyContinue|Where-Object{$_.Name -match '^brave' -and $_.CommandLine -match '(?i)--load-extension='})){foreach($arg in [regex]::Matches($proc.CommandLine,'--load-extension=(?:"([^"]+)"|([^\s]+))')){$d=$arg.Groups[1].Value;if([string]::IsNullOrWhiteSpace($d)){$d=$arg.Groups[2].Value};if(IsUntrappedManifest $d){$o+=$d;Log ('[BRAVE] --load-extension copy found: '+$d)}}};@($o|Sort-Object -Unique)}
function Diagnose([string]$phase){$p=@();$c=$null;$scheduled=$false;$override=$false;Log ('[DIAGNOSTIC] '+$phase+' diagnostic begins.');try{$c=Get-Content (Join-Path $Root 'config.json') -Raw|ConvertFrom-Json;$a=[TimeSpan]::Parse($c.start);$b=[TimeSpan]::Parse($c.end);$n=(Get-Date).TimeOfDay;if($a -lt $b){$inside=($n -ge $a -and $n -lt $b)}else{$inside=($n -ge $a -or $n -lt $b)};$o=Join-Path $Root 'override-until.txt';if(Test-Path $o){try{$override=[DateTime]::UtcNow -lt ([DateTime]::Parse((Get-Content $o -Raw)).ToUniversalTime())}catch{$p+='Override file is unreadable.'}};$scheduled=[bool]($c.enabled -and $inside -and -not $override);Write-Host ('[STATUS] Policy: '+(StateWord ([bool]$c.enabled) 'ENABLED' 'DISABLED'));Write-Host ('[STATUS] Schedule: '+$c.start+' - '+$c.end);Write-Host ('[STATUS] Scheduled blocking: '+(StateWord $scheduled 'ACTIVE' 'INACTIVE'));Write-Host ('[STATUS] Override: '+(StateWord $override 'ACTIVE' 'INACTIVE'))}catch{$p+='Config is invalid or unreadable.'};$yt=HTTPS 'www.youtube.com';$ch=HTTPS 'chatgpt.com';$cr=HTTPS 'www.crushon.ai';$want=-not $scheduled;Write-Host ('[STATUS] YouTube transport: '+(StateWord $yt 'REACHABLE' 'UNREACHABLE'));Write-Host ('[STATUS] ChatGPT transport: '+(StateWord $ch 'REACHABLE' 'UNREACHABLE'));Write-Host ('[STATUS] CrushOn transport: '+(StateWord $cr 'REACHABLE' 'UNREACHABLE'));if($c){if($yt -ne $want){$p+='YouTube transport does not match configured policy.'};if($ch -ne $want){$p+='ChatGPT transport does not match configured policy.'};if($cr){$p+='CrushOn is reachable despite always-block policy.'}};$bad=@();$unknown=@();foreach($f in $core){$x=Same ('ultra-mode/'+$f) (Join-Path $Root $f);if($x -eq $false){$bad+=$f}elseif($null -eq $x){$unknown+=$f}};if($bad.Count){$coreState='MISMATCH'}elseif($unknown.Count){$coreState='UNVERIFIED'}else{$coreState='CURRENT'};Write-Host ('[STATUS] Core source vs Railway manifest: '+$coreState);if($bad.Count){$p+='Untrapped core differs from canonical Railway artifact: '+($bad -join ', ')};if($unknown.Count){$p+='Untrapped core could not be verified: '+($unknown -join ', ')};$nativeOK=(Test-Path (Join-Path $Root 'WinDivert.dll')) -and (Test-Path (Join-Path $Root 'WinDivert64.sys'));Write-Host ('[STATUS] WinDivert native files: '+(StateWord $nativeOK 'PRESENT' 'MISSING'));if(!$nativeOK){$p+='Required WinDivert native component is missing.'};$packet=@(Get-CimInstance Win32_Process -ErrorAction SilentlyContinue|Where-Object{$_.CommandLine -like '*packet-filter.ps1*'});$control=@(Get-CimInstance Win32_Process -ErrorAction SilentlyContinue|Where-Object{$_.CommandLine -like '*ultra-mode.ps1*'});Write-Host ('[STATUS] Packet filter: '+(StateWord ([bool]$packet.Count) 'RUNNING' 'STOPPED'));Write-Host ('[STATUS] Control plane: '+(StateWord ([bool]$control.Count) 'RUNNING' 'STOPPED'));if(!$packet.Count){$p+='Packet filter is not running.'};if(!$control.Count){$p+='Control plane is not running.'};$ebad=@();$eunknown=@();foreach($f in $ext){$x=Same $f (Join-Path $Parent $f);if($x -eq $false){$ebad+=$f}elseif($null -eq $x){$eunknown+=$f}};if($ebad.Count){$extState='MISMATCH'}elseif($eunknown.Count){$extState='UNVERIFIED'}else{$extState='CURRENT'};Write-Host ('[STATUS] Extension source vs Railway manifest: '+$extState);if($ebad.Count){$p+='Enhanced extension source differs from canonical Railway artifact: '+($ebad -join ', ')};if($eunknown.Count){$p+='Enhanced extension source could not be verified: '+($eunknown -join ', ')};$bc=BraveCopies;Write-Host ('[STATUS] Brave Untrapped copies: '+$bc.Count+' '+(StateWord ([bool]$bc.Count) 'FOUND' 'NOT FOUND - INFORMATIONAL'));$dns=$false;try{$dns=@(Resolve-DnsName google.com -DnsOnly -ErrorAction Stop|Where-Object{$_.IPAddress}).Count -gt 0}catch{};$goo=HTTPS 'www.google.com';$bfe=$false;try{$bfe=(Get-Service BFE).Status -eq 'Running'}catch{};$hp=Join-Path $env:SystemRoot 'System32\drivers\etc\hosts';$hosts=@();if(Test-Path $hp){$hosts=@(Get-Content $hp|Where-Object{$_ -match '(?i)(youtube|youtu\.be|chatgpt|crushon)' -and $_ -notmatch '^\s*#'})};Write-Host ('[STATUS] DNS: '+(StateWord $dns 'OK' 'FAILED'));Write-Host ('[STATUS] Google HTTPS: '+(StateWord $goo 'OK' 'FAILED'));Write-Host ('[STATUS] Relevant Hosts entries: '+$hosts.Count);Write-Host ('[STATUS] BFE: '+(StateWord $bfe 'RUNNING' 'NOT RUNNING/UNKNOWN'));if(!$dns){$p+='External DNS resolution is failing.'};if(!$goo){$p+='External HTTPS connectivity to Google is failing.'};if($hosts.Count){$p+='Relevant Hosts entries were found.'};if(!$bfe){$p+='Base Filtering Engine is not running.'};return @{Problems=@($p);CoreBad=$bad;CoreUnknown=$unknown;ExtBad=$ebad;ExtUnknown=$eunknown;Brave=$bc;Packet=$packet;Control=$control;Dns=$dns;Google=$goo;Hosts=$hosts;Bfe=$bfe}}
function DeployUARD{Log '[UARD DEPLOY] Checking canonical UARD through Railway middleman.';$r=Remote 'ultra-mode/self-repair.ps1';if($null -eq $r){return 'UNVERIFIED'};try{[void][scriptblock]::Create([Text.Encoding]::UTF8.GetString($r))}catch{Log ('[UARD DEPLOY] Canonical UARD failed PowerShell parsing: '+$_.Exception.Message);return 'FAILED'};$lv=[version]'0.0.0';if(Test-Path $RepairPath){try{$lv=VersionOf ([IO.File]::ReadAllBytes($RepairPath))}catch{}};Write-Host ('[BASELINE] Installed UARD version: '+$lv);Write-Host '[BASELINE] Canonical minimum: 1.0.0';if($lv -lt [version]'1.0.0'){Log '[BASELINE] Installed UARD is below protected baseline; deployment required if canonical is valid.'};if((Test-Path $RepairPath) -and (Hash ([IO.File]::ReadAllBytes($RepairPath))) -eq (Hash $r)){Log '[UARD DEPLOY] Current; no deployment required.';return 'CURRENT'};$tmp=$RepairPath+'.deploy.tmp';try{$bak=$RepairPath+'.pre-deploy-'+(Get-Date -Format yyyyMMdd-HHmmss)+'.bak';if(Test-Path $RepairPath){Copy-Item $RepairPath $bak -Force;Log ('[UARD DEPLOY] Backup '+$bak)};[IO.File]::WriteAllBytes($tmp,$r);if((Hash ([IO.File]::ReadAllBytes($tmp))) -ne (Hash $r)){throw 'SHA-256 deployment verification failed.'};Move-Item $tmp $RepairPath -Force;if((Hash ([IO.File]::ReadAllBytes($RepairPath))) -ne (Hash $r)){throw 'Post-deployment SHA-256 verification failed.'};Log '[UARD DEPLOY] Deployed and verified.';return 'DEPLOYED'}catch{Log ('[UARD DEPLOY] FAILED: '+$_.Exception.Message);Remove-Item $tmp -Force -ErrorAction SilentlyContinue;return 'FAILED'}}
[Net.ServicePointManager]::SecurityProtocol=[Net.SecurityProtocolType]::Tls12;Log "=== $UAUDName ver $UAUDVersion ===";Log 'TRUE BASELINE 1.0.0: retained or upgraded, never silently downgraded.';Log 'MIDDLEMAN: Railway is the update comparison source.';$d=Diagnose 'INITIAL';$initialProblems=@($d.Problems);$UARDNeeded=($initialProblems.Count -gt 0);if($UARDNeeded){Write-Host '[UARD DECISION] Is UARD needed? YES - actionable diagnostic condition found.'}else{Write-Host '[UARD DECISION] Is UARD needed? NO - no actionable repair condition.'};Log ('[UARD DECISION] UARD NEEDED = '+(StateWord $UARDNeeded 'YES' 'NO'));if($UARDNeeded){$deployment=DeployUARD;if($deployment -eq 'DEPLOYED' -or $deployment -eq 'CURRENT'){$p=Start-Process powershell.exe -ArgumentList @('-NoProfile','-ExecutionPolicy','Bypass','-File',$RepairPath) -WorkingDirectory $Root -WindowStyle Normal -PassThru -ErrorAction SilentlyContinue;if($p){Log '[UARD] LIVE PowerShell window created.';$p.WaitForExit();if($p.ExitCode -eq 0){$repairResult='SUCCESS'}elseif($p.ExitCode -eq 2){$repairResult='VERIFICATION UNKNOWN'}else{$repairResult='FAILURE'};Log ('[UARD] LIVE window closed. Exit code '+$p.ExitCode+' / '+$repairResult)}else{$repairResult='START FAILURE';Log '[UARD] LIVE PowerShell window could not be created.'}}else{$repairResult='NOT LAUNCHED';Log '[UARD] Not launched; canonical UARD was not safely deployed.'}}else{Log '[DIAGNOSTIC] UARD not needed.'};Log '[DIAGNOSTIC] Final verification begins.';$f=Diagnose 'FINAL';$remaining=@($f.Problems);$overall='HEALTHY';if($remaining.Count){$overall='UNHEALTHY'};$out=@('CONDENSED DIAGNOSIS',' OVERALL: '+$overall,' UAUD: '+$UAUDName+' ver '+$UAUDVersion,' UARD NEEDED: '+(StateWord $UARDNeeded 'YES' 'NO'),' UARD deployment: '+$deployment,' UARD result: '+$repairResult,' MIDDLEMAN: Railway update broker',' UPDATE NORMALIZATION: reported by UARD when applicable',' Brave copies: '+$f.Brave.Count,' Remaining problems: '+$remaining.Count);foreach($x in $remaining){$out+=' ! '+$x};$out+=@('','EXPLANATORY TABLE','Component | Owner | Behaviour','UAUD | Update + diagnosis | Uses Railway manifest as canonical comparison authority and decides whether UARD is needed','UARD | Repair + verification | Repairs Untrapped-owned components, validates SHA-256, and reports normalization','Live PowerShell | UARD | Visible only while UARD actively repairs; closes on exit','Notepad | Both | UARD report opens on repair/failure; UAUD diagnostic report always opens','Baseline | UAUD + UARD | 1.0.0 protected; upgrades allowed; downgrades refused','Brave | UAUD + UARD | Packaged and developer-loaded copies detected; source copy is explicitly recognised','Network infrastructure | Diagnosis only | Firewall/WFP/DNS/routes/Hosts/proxy/adapters/VPN/override policy are not modified');$out|Set-Content $ReportPath -Encoding UTF8;$log|Add-Content $ReportPath -Encoding UTF8;Start-Process notepad.exe -ArgumentList @($ReportPath) -ErrorAction SilentlyContinue